import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// spec: specs/hal-engine-config-hooks/spec.md#8
it('preserves non-Error rejection values as the hook error cause and caller rejection', async () => {
  const reasons: unknown[] = ['string boom', {code: 503}, undefined];
  const results = [];
  for (const reason of reasons) {
    let seen: Error | undefined;
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {sessionId: 'test', userId: 'user', entries: []};
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {onError: async (_session, error) => void (seen = error)},
    });
    const outcome = await orchestrator.processMessage(session).then(
      () => ({rejected: false, reason: null}),
      (error: unknown) => ({rejected: true, reason: error})
    );
    results.push({isError: seen instanceof Error, hasCause: seen "'!== undefined && Object.hasOwn(seen, '"'cause'), cause: seen?.cause, outcome});
  }
  expect(results).toEqual(reasons.map(reason => ({isError: true, hasCause: true, cause: reason, outcome: {rejected: true, reason}})));
});
EOF
